  "concepts": ["AI-assisted creative production", "audience-response-informed workflows", "commercial evaluation of AI outputs", "human-AI collaboration in marketing", "creative selection vs generation"],
  "connections": [
    {
      "to": 2,
      "kind": "related",
      "why": "Both sources distinguish between ordinary AI output (which tends toward average/common responses) and trained/selected workflows that can surface stronger candidates."
    },
    {
      "to": 8,
      "kind": "related",
      "why": "Both examine how AI redistributes creative work—this review details workflow stages where humans remain involved (briefing, review, selection), while #8 studies job-posting and survey evidence on shifting creative roles."
